 assert.equal(C.controls.final.path,v51eB+'city4-plunder-source-controls-v2.json');const control=v51eJson(files,C.controls.final);assert.equal(control.accepted,true);assert.equal(control.sourceStable,true);assert.deepEqual(control.before,control.after);assert.equal(control.sourceCount,control.after.length);assert.equal(control.target.status,0);assert.equal(control.expectedTests,23);assert.deepEqual([control.target.tests,control.target.pass],[23,23]);for(const k of['fail','cancelled','skipped','todo'])assert.equal(control.target[k],0);assert.deepEqual(v51eStats(v51eArchive(files,control.target.stdout)),{tests:23,pass:23,fail:0,cancelled:0,skipped:0,todo:0});assert.equal(v51eArchive(files,control.target.stderr).length,0);for(const k of['actualGameExecuted','browserStarted','defaultOrFullSuiteRun'])assert.equal(control[k],false);assert.equal(control.defaultTestsAdded,0);
 assert.equal(C.controls.first.path,v51eB+'city4-plunder-source-controls-v1.json');const first=v51eJson(files,C.controls.first);assert.equal(first.accepted,false);assert.equal(first.sourceStable,true);assert.deepEqual(first.before,first.after);assert.equal(first.target.status,1);assert.deepEqual([first.expectedTests,first.target.tests,first.target.pass,first.target.fail],[23,23,21,2]);for(const k of['cancelled','skipped','todo'])assert.equal(first.target[k],0);assert.deepEqual(v51eStats(v51eArchive(files,first.target.stdout)),{tests:23,pass:21,fail:2,cancelled:0,skipped:0,todo:0});assert.equal(v51eArchive(files,first.target.stderr).length,0);
 assert.ok(Array.isArray(C.controls.firstCopies)&&C.controls.firstCopies.length===2);const oldController=v51eRows(first.finalControllerSources,'Original rejected controls source'),oldSeen=new Set();for(const x of C.controls.firstCopies){assert.ok(['test-city4-plunder-source-v1.mjs','run-october-city4-plunder-v1.mjs'].map(n=>v51eB+'city4-plunder-20261024-source-v1/'+n).includes(x.source));assert.ok(!oldSeen.has(x.source));oldSeen.add(x.source);const b=v51eArchive(files,x.copy),p=oldController.get(x.source);assert.deepEqual([b.length,v51eSha(b)],[p.bytes,p.sha256],'First rejected test/metadata-binding source bytes retained');}

 const libPin={path:'libs/dat-mod.lib',bytes:207195,sha256:'3bd20146084054163d045c90987c756a6a210664e78253cc56bc4a274727903e'},libBytes=v51eBytes(readCurrent(libPin.path),libPin),actualFiles=new Map(files);for(const[p,b]of priorBytes)actualFiles.set(p,b);if(actualFiles.has(libPin.path))v51eBytes(actualFiles.get(libPin.path),libPin);else actualFiles.set(libPin.path,libBytes);
