const V51_PREFIX='docs/validation/m5-wood-city4-plunder-20261024-v51';
export function verifyV51Publication(root=process.cwd(),options={}){
 const readPublic=options.readPublic??(p=>v45ReadBounded(root,p)),readCurrent=options.readCurrent??(p=>{try{return v45ReadBounded(root,p);}catch(e){if(e.code==='ENOENT')return null;throw e;}});
 const C=JSON.parse(readPublic(V51_PREFIX+'.json'));assert.ok(Object.hasOwn(C,'observations'),'Complete canonical observations are mandatory');assert.equal(C.reader.path,V51_PREFIX+'-verify.mjs');assert.deepEqual(v45Pin(C.reader.path,readPublic(C.reader.path)),C.reader);assert.equal(C.readerDependency.path,'docs/validation/m5-quantity-ack-refresh-20261024-v45-verify.mjs');assert.deepEqual(v45Pin(C.readerDependency.path,readCurrent(C.readerDependency.path)),C.readerDependency);
 const index=JSON.parse(readPublic(C.archive.path)),decoded=decodeV45Archive({index,readPart:p=>readPublic(p)}),r=verifyV51Envelope({files:decoded.files,canonical:C,readPublic,readCurrent,verifyActual:verifyV51City4PlunderActual,readLatestOctoberInput,OCTOBER_INPUT_PINS,CITY4_HISTORY_INPUT_PINS});
 const pngs=[];for(const[p,b]of decoded.files)if(p.startsWith(C.runDir)&&p.endsWith('.png'))pngs.push({pin:v45Pin(p,b),decoded:decodeV45Png(b)});assert.deepEqual(pngs,C.pngs,'Every original ordinary PNG is fully decoded');return{accepted:true,logicalFiles:decoded.logicalFiles,uniqueBlobs:decoded.physicalBlobs,ordinaryPngsDecoded:pngs.length,sourceBinding:r.sourceBinding,facts:r.facts,newBrowserRuns:0,newGameInputs:0,newDefaultTestExecutions:0,actualFlagsRewritten:false};
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){const r=verifyV51Publication();console.log(JSON.stringify({accepted:r.accepted,logicalFiles:r.logicalFiles,ordinaryPngsDecoded:r.ordinaryPngsDecoded,sourceBinding:r.sourceBinding,newPlunders:r.facts.actual.newPlunders,thewSpent:r.facts.actual.thewSpent,freshFullTests:r.facts.full.tests,newDefaultTestExecutionsByReader:0,sourceControls:r.facts.controls.tests,globalHdComplete:false}));}
